def find_chain(start, end):
    stack = [(start, '')]
    visited = set()
    while stack:
        current, path = stack.pop()
        if current == end:
            return path
        if current in visited:
            continue
        visited.add(current)
        for next_char in 'abcdefghijklmnopqrstuvwxyz':
            next_word = current + next_char
            if next_word not in visited:
                stack.append((next_word, path + next_char))
    return None

